    25→void swap_blocks(torch::Tensor& src, torch::Tensor& dst,
    26→                 const torch::Tensor& block_mapping) {
    27→  torch::Device src_device = src.device();
    28→  torch::Device dst_device = dst.device();
    29→  cudaMemcpyKind memcpy_type;
    30→  if (src_device.is_cuda() && dst_device.is_cuda()) {
    31→    TORCH_CHECK(src_device.index() == dst_device.index(),
    32→                "src and dst must be on the same GPU");
    33→    memcpy_type = cudaMemcpyDeviceToDevice;
    34→  } else if (src_device.is_cuda() && dst_device.is_cpu()) {
    35→    memcpy_type = cudaMemcpyDeviceToHost;
    36→  } else if (src_device.is_cpu() && dst_device.is_cuda()) {
    37→    memcpy_type = cudaMemcpyHostToDevice;
    38→  } else {
    39→    TORCH_CHECK(false, "Invalid device combination");
    40→  }
    41→
    42→  // NOTE(youkaichao): keep in mind that `block_mapping` should be
    43→  // a cpu tensor, otherwise every `item` call will require a gpu-cpu
    44→  // synchronization.
    45→  TORCH_CHECK(block_mapping.device().is_cpu(), "block_mapping must be on CPU");
    46→
    47→  char* src_ptr = static_cast<char*>(src.data_ptr());
    48→  char* dst_ptr = static_cast<char*>(dst.data_ptr());
    49→
    50→  // We use the stride instead of numel in case the cache is padded for memory
    51→  // alignment reasons, we assume the blocks data (inclusive of any padding)
    52→  // is contiguous in memory
    53→  const int64_t block_size_in_bytes = src.element_size() * src.stride(0);
    54→  const at::cuda::OptionalCUDAGuard device_guard(
    55→      src_device.is_cuda() ? src_device : dst_device);
    56→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    57→  // NOTE(woosuk): This can be slow if the number of blocks is large.
    58→  const int64_t num_blocks = block_mapping.size(0);
    59→  for (size_t i = 0; i < num_blocks; i++) {
    60→    int64_t src_block_number = block_mapping[i][0].item<int64_t>();
    61→    int64_t dst_block_number = block_mapping[i][1].item<int64_t>();
    62→    int64_t src_offset = src_block_number * block_size_in_bytes;
    63→    int64_t dst_offset = dst_block_number * block_size_in_bytes;
    64→    cudaMemcpyAsync(dst_ptr + dst_offset, src_ptr + src_offset,
    65→                    block_size_in_bytes, memcpy_type, stream);
    66→  }
    67→}
