    71→// Grid: (num_layers, num_pairs)
    72→template <typename scalar_t>
    73→__global__ void copy_blocks_kernel(int64_t* key_cache_ptrs,
    74→                                   int64_t* value_cache_ptrs,
    75→                                   const int64_t* __restrict__ block_mapping,
    76→                                   const int numel_per_block) {
    77→  const int layer_idx = blockIdx.x;
    78→  const int pair_idx = blockIdx.y;
    79→
    80→  scalar_t* key_cache = reinterpret_cast<scalar_t*>(key_cache_ptrs[layer_idx]);
    81→  scalar_t* value_cache =
    82→      reinterpret_cast<scalar_t*>(value_cache_ptrs[layer_idx]);
    83→  int64_t src_block_number = block_mapping[2 * pair_idx];
    84→  int64_t dst_block_number = block_mapping[2 * pair_idx + 1];
    85→
    86→  const int64_t src_block_offset = src_block_number * numel_per_block;
    87→  const int64_t dst_block_offset = dst_block_number * numel_per_block;
    88→  for (int i = threadIdx.x; i < numel_per_block; i += blockDim.x) {
    89→    int64_t src_offset = src_block_offset + i;
    90→    int64_t dst_offset = dst_block_offset + i;
    91→    scalar_t tmp_k = key_cache[src_offset];
    92→    scalar_t tmp_v = value_cache[src_offset];
    93→    key_cache[dst_offset] = tmp_k;
    94→    value_cache[dst_offset] = tmp_v;
    95→  }
    96→}
