    98→// Kernel for MLA, which works on a single joint kv_cache
    99→// Grid: (num_layers, num_pairs)
   100→template <typename scalar_t>
   101→__global__ void copy_blocks_mla_kernel(
   102→    int64_t* cache_ptrs, const int64_t* __restrict__ block_mapping,
   103→    const int mem_footprint_per_block) {
   104→  const int layer_idx = blockIdx.x;
   105→  const int pair_idx = blockIdx.y;
   106→  scalar_t* cache = reinterpret_cast<scalar_t*>(cache_ptrs[layer_idx]);
   107→  int64_t src_block = block_mapping[2 * pair_idx];
   108→  int64_t dst_block = block_mapping[2 * pair_idx + 1];
   109→  int64_t src_offset = src_block * mem_footprint_per_block;
   110→  int64_t dst_offset = dst_block * mem_footprint_per_block;
   111→  for (int i = threadIdx.x; i < mem_footprint_per_block; i += blockDim.x) {
   112→    cache[dst_offset + i] = cache[src_offset + i];
   113→  }
   114→}
