   118→// Note: the key_caches and value_caches vectors are constant but
   119→// not the Tensors they contain. The vectors need to be const refs
   120→// in order to satisfy pytorch's C++ operator registration code.
   121→void copy_blocks(std::vector<torch::Tensor> const& key_caches,
   122→                 std::vector<torch::Tensor> const& value_caches,
   123→                 const torch::Tensor& block_mapping) {
   124→  int num_layers = key_caches.size();
   125→  TORCH_CHECK(num_layers == value_caches.size());
   126→  if (num_layers == 0) {
   127→    return;
   128→  }
   129→  torch::Device cache_device = key_caches[0].device();
   130→  TORCH_CHECK(cache_device.is_cuda());
   131→
   132→  // Create data structures for the kernel.
   133→  // Create an array of pointers to the key and value caches.
   134→  int64_t key_cache_ptrs[num_layers];
   135→  int64_t value_cache_ptrs[num_layers];
   136→  for (int layer_idx = 0; layer_idx < num_layers; ++layer_idx) {
   137→    key_cache_ptrs[layer_idx] =
   138→        reinterpret_cast<int64_t>(key_caches[layer_idx].data_ptr());
   139→    value_cache_ptrs[layer_idx] =
   140→        reinterpret_cast<int64_t>(value_caches[layer_idx].data_ptr());
   141→  }
   142→
   143→  // block_mapping is a 2D tensor with shape (num_pairs, 2).
   144→  int num_pairs = block_mapping.size(0);
   145→
   146→  // Move the data structures to the GPU.
   147→  // NOTE: This synchronizes the CPU and GPU.
   148→  torch::Tensor key_cache_ptrs_tensor =
   149→      torch::from_blob(key_cache_ptrs, {num_layers}, torch::kInt64)
   150→          .to(cache_device);
   151→  torch::Tensor value_cache_ptrs_tensor =
   152→      torch::from_blob(value_cache_ptrs, {num_layers}, torch::kInt64)
   153→          .to(cache_device);
   154→
   155→  // Launch the kernel.
   156→  const int numel_per_block = key_caches[0][0].numel();
   157→  dim3 grid(num_layers, num_pairs);
   158→  dim3 block(std::min(1024, numel_per_block));
   159→  const at::cuda::OptionalCUDAGuard device_guard(cache_device);
   160→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   161→  VLLM_DISPATCH_FLOATING_AND_BYTE_TYPES(
   162→      key_caches[0].scalar_type(), "copy_blocks_kernel", ([&] {
   163→        vllm::copy_blocks_kernel<scalar_t><<<grid, block, 0, stream>>>(
   164→            key_cache_ptrs_tensor.data_ptr<int64_t>(),
   165→            value_cache_ptrs_tensor.data_ptr<int64_t>(),
   166→            block_mapping.data_ptr<int64_t>(), numel_per_block);
   167→      }));
   168→}
