   170→// copy blocks kernel for MLA (assumes a joint KV-cache)
   171→void copy_blocks_mla(std::vector<torch::Tensor> const& kv_caches,
   172→                     const torch::Tensor& block_mapping) {
   173→  int num_layers = kv_caches.size();
   174→  if (num_layers == 0) {
   175→    return;
   176→  }
   177→  torch::Device cache_device = kv_caches[0].device();
   178→  TORCH_CHECK(cache_device.is_cuda(), "kv_cache must be on CUDA");
   179→
   180→  std::vector<int64_t> cache_ptrs(num_layers);
   181→  for (int layer_idx = 0; layer_idx < num_layers; ++layer_idx) {
   182→    cache_ptrs[layer_idx] =
   183→        reinterpret_cast<int64_t>(kv_caches[layer_idx].data_ptr());
   184→  }
   185→  torch::Tensor cache_ptrs_tensor =
   186→      torch::from_blob(cache_ptrs.data(), {num_layers}, torch::kInt64)
   187→          .to(cache_device);
   188→
   189→  int num_pairs = block_mapping.size(0);
   190→  // We use the stride instead of numel in case the cache is padded for memory
   191→  // alignment reasons, we assume the blocks data (inclusive of any padding)
   192→  // is contiguous in memory
   193→  int mem_footprint_per_block = kv_caches[0].stride(0);
   194→  dim3 grid(num_layers, num_pairs);
   195→  dim3 block(std::min(1024, mem_footprint_per_block));
   196→  const at::cuda::OptionalCUDAGuard device_guard(cache_device);
   197→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   198→  VLLM_DISPATCH_FLOATING_AND_BYTE_TYPES(
   199→      kv_caches[0].scalar_type(), "copy_blocks_mla_kernel", ([&] {
   200→        vllm::copy_blocks_mla_kernel<scalar_t><<<grid, block, 0, stream>>>(
   201→            cache_ptrs_tensor.data_ptr<int64_t>(),
   202→            block_mapping.data_ptr<int64_t>(), mem_footprint_per_block);
   203→      }));
   204→}
