   208→template <typename scalar_t, typename cache_t, Fp8KVCacheDataType kv_dt>
   209→__global__ void reshape_and_cache_kernel(
   210→    const scalar_t* __restrict__ key,    // [num_tokens, num_heads, head_size]
   211→    const scalar_t* __restrict__ value,  // [num_tokens, num_heads, head_size]
   212→    cache_t* __restrict__ key_cache,     // [num_blocks, num_heads, head_size/x,
   213→                                         // block_size, x]
   214→    cache_t* __restrict__ value_cache,   // [num_blocks, num_heads, head_size,
   215→                                         // block_size]
   216→    const int64_t* __restrict__ slot_mapping,  // [num_tokens]
   217→    const int key_stride, const int value_stride, const int num_heads,
   218→    const int head_size, const int block_size, const int x,
   219→    const float* k_scale, const float* v_scale) {
   220→  const int64_t token_idx = blockIdx.x;
   221→  const int64_t slot_idx = slot_mapping[token_idx];
   222→  if (slot_idx < 0) {
   223→    // Padding token that should be ignored.
   224→    return;
   225→  }
   226→
   227→  const int64_t block_idx = slot_idx / block_size;
   228→  const int64_t block_offset = slot_idx % block_size;
   229→
   230→  const int n = num_heads * head_size;
   231→  for (int i = threadIdx.x; i < n; i += blockDim.x) {
   232→    const int64_t src_key_idx = token_idx * key_stride + i;
   233→    const int64_t src_value_idx = token_idx * value_stride + i;
   234→
   235→    const int head_idx = i / head_size;
   236→    const int head_offset = i % head_size;
   237→    const int x_idx = head_offset / x;
   238→    const int x_offset = head_offset % x;
   239→
   240→    const int64_t tgt_key_idx =
   241→        block_idx * num_heads * (head_size / x) * block_size * x +
   242→        head_idx * (head_size / x) * block_size * x + x_idx * block_size * x +
   243→        block_offset * x + x_offset;
   244→    const int64_t tgt_value_idx =
   245→        block_idx * num_heads * head_size * block_size +
   246→        head_idx * head_size * block_size + head_offset * block_size +
   247→        block_offset;
   248→    scalar_t tgt_key = key[src_key_idx];
   249→    scalar_t tgt_value = value[src_value_idx];
   250→    if constexpr (kv_dt == Fp8KVCacheDataType::kAuto) {
   251→      key_cache[tgt_key_idx] = tgt_key;
   252→      value_cache[tgt_value_idx] = tgt_value;
   253→    } else {
   254→      key_cache[tgt_key_idx] =
   255→          fp8::scaled_convert<cache_t, scalar_t, kv_dt>(tgt_key, *k_scale);
   256→      value_cache[tgt_value_idx] =
   257→          fp8::scaled_convert<cache_t, scalar_t, kv_dt>(tgt_value, *v_scale);
   258→    }
   259→  }
   260→}
