   262→template <typename scalar_t, typename cache_t, Fp8KVCacheDataType kv_dt>
   263→__global__ void reshape_and_cache_flash_kernel(
   264→    const scalar_t* __restrict__ key,    // [num_tokens, num_heads, head_size]
   265→    const scalar_t* __restrict__ value,  // [num_tokens, num_heads, head_size]
   266→    cache_t* __restrict__ key_cache,     // [num_blocks, block_size, num_heads,
   267→                                         // head_size]
   268→    cache_t* __restrict__ value_cache,   // [num_blocks, block_size, num_heads,
   269→                                         // head_size]
   270→    const int64_t* __restrict__ slot_mapping,  // [num_tokens]
   271→    const int64_t block_stride, const int64_t page_stride,
   272→    const int64_t head_stride, const int64_t key_stride,
   273→    const int64_t value_stride, const int num_heads, const int head_size,
   274→    const int block_size, const float* k_scale, const float* v_scale) {
   275→  const int64_t token_idx = blockIdx.x;
   276→  const int64_t slot_idx = slot_mapping[token_idx];
   277→  // NOTE: slot_idx can be -1 if the token is padded
   278→  if (slot_idx < 0) {
   279→    return;
   280→  }
   281→  const int64_t block_idx = slot_idx / block_size;
   282→  const int64_t block_offset = slot_idx % block_size;
   283→
   284→  // Precompute base pointers to reduce index math in the inner loop.
   285→  const scalar_t* __restrict__ key_base = key + token_idx * key_stride;
   286→  const scalar_t* __restrict__ value_base = value + token_idx * value_stride;
   287→  cache_t* __restrict__ key_cache_base =
   288→      key_cache + block_idx * block_stride + block_offset * page_stride;
   289→  cache_t* __restrict__ value_cache_base =
   290→      value_cache + block_idx * block_stride + block_offset * page_stride;
   291→
   292→  // Iterate over heads outside and head_size inside to avoid expensive
   293→  // div/mod operations on each iteration.
   294→  for (int head_idx = 0; head_idx < num_heads; ++head_idx) {
   295→    const int64_t src_head_off = static_cast<int64_t>(head_idx) * head_size;
   296→    const int64_t tgt_head_off = static_cast<int64_t>(head_idx) * head_stride;
   297→    for (int ho = threadIdx.x; ho < head_size; ho += blockDim.x) {
   298→      const scalar_t k_val = key_base[src_head_off + ho];
   299→      const scalar_t v_val = value_base[src_head_off + ho];
   300→      const int64_t tgt_idx = tgt_head_off + static_cast<int64_t>(ho);
   301→      if constexpr (kv_dt == Fp8KVCacheDataType::kAuto) {
   302→        key_cache_base[tgt_idx] = k_val;
   303→        value_cache_base[tgt_idx] = v_val;
   304→      } else {
   305→        key_cache_base[tgt_idx] =
   306→            fp8::scaled_convert<cache_t, scalar_t, kv_dt>(k_val, *k_scale);
   307→        value_cache_base[tgt_idx] =
   308→            fp8::scaled_convert<cache_t, scalar_t, kv_dt>(v_val, *v_scale);
   309→      }
   310→    }
   311→  }
   312→}
