   314→template <typename scalar_t, typename cache_t, Fp8KVCacheDataType kv_dt>
   315→__global__ void concat_and_cache_mla_kernel(
   316→    const scalar_t* __restrict__ kv_c,  // [num_tokens, kv_lora_rank]
   317→    const scalar_t* __restrict__ k_pe,  // [num_tokens, pe_dim]
   318→    cache_t* __restrict__ kv_cache,  // [num_blocks, block_size, (kv_lora_rank
   319→                                     // + pe_dim)]
   320→    const int64_t* __restrict__ slot_mapping,  // [num_tokens]
   321→    const int block_stride,                    //
   322→    const int entry_stride,                    //
   323→    const int kv_c_stride,                     //
   324→    const int k_pe_stride,                     //
   325→    const int kv_lora_rank,                    //
   326→    const int pe_dim,                          //
   327→    const int block_size,                      //
   328→    const float* scale                         //
   329→) {
   330→  const int64_t token_idx = blockIdx.x;
   331→  const int64_t slot_idx = slot_mapping[token_idx];
   332→  // NOTE: slot_idx can be -1 if the token is padded
   333→  if (slot_idx < 0) {
   334→    return;
   335→  }
   336→  const int64_t block_idx = slot_idx / block_size;
   337→  const int64_t block_offset = slot_idx % block_size;
   338→
   339→  auto copy = [&](const scalar_t* __restrict__ src, cache_t* __restrict__ dst,
   340→                  int src_stride, int dst_stride, int size, int offset) {
   341→    for (int i = threadIdx.x; i < size; i += blockDim.x) {
   342→      const int64_t src_idx = token_idx * src_stride + i;
   343→      const int64_t dst_idx =
   344→          block_idx * block_stride + block_offset * entry_stride + i + offset;
   345→      if constexpr (kv_dt == Fp8KVCacheDataType::kAuto) {
   346→        dst[dst_idx] = src[src_idx];
   347→      } else {
   348→        dst[dst_idx] =
   349→            fp8::scaled_convert<cache_t, scalar_t, kv_dt>(src[src_idx], *scale);
   350→      }
   351→    }
   352→  };
   353→
   354→  copy(kv_c, kv_cache, kv_c_stride, block_stride, kv_lora_rank, 0);
   355→  copy(k_pe, kv_cache, k_pe_stride, block_stride, pe_dim, kv_lora_rank);
   356→}
