   360→// KV_T is the data type of key and value tensors.
   361→// CACHE_T is the stored data type of kv-cache.
   362→// KV_DTYPE is the real data type of kv-cache.
   363→#define CALL_RESHAPE_AND_CACHE(KV_T, CACHE_T, KV_DTYPE)               \
   364→  vllm::reshape_and_cache_kernel<KV_T, CACHE_T, KV_DTYPE>             \
   365→      <<<grid, block, 0, stream>>>(                                   \
   366→          reinterpret_cast<KV_T*>(key.data_ptr()),                    \
   367→          reinterpret_cast<KV_T*>(value.data_ptr()),                  \
   368→          reinterpret_cast<CACHE_T*>(key_cache.data_ptr()),           \
   369→          reinterpret_cast<CACHE_T*>(value_cache.data_ptr()),         \
   370→          slot_mapping.data_ptr<int64_t>(), key_stride, value_stride, \
   371→          num_heads, head_size, block_size, x,                        \
   372→          reinterpret_cast<const float*>(k_scale.data_ptr()),         \
   373→          reinterpret_cast<const float*>(v_scale.data_ptr()));
   374→
   375→void reshape_and_cache(
   376→    torch::Tensor& key,    // [num_tokens, num_heads, head_size]
   377→    torch::Tensor& value,  // [num_tokens, num_heads, head_size]
   378→    torch::Tensor&
   379→        key_cache,  // [num_blocks, num_heads, head_size/x, block_size, x]
   380→    torch::Tensor&
   381→        value_cache,  // [num_blocks, num_heads, head_size, block_size]
   382→    torch::Tensor& slot_mapping,  // [num_tokens]
   383→    const std::string& kv_cache_dtype, torch::Tensor& k_scale,
   384→    torch::Tensor& v_scale) {
   385→  int num_tokens = slot_mapping.size(0);
   386→  int num_heads = key.size(1);
   387→  int head_size = key.size(2);
   388→  int block_size = key_cache.size(3);
   389→  int x = key_cache.size(4);
   390→
   391→  int key_stride = key.stride(0);
   392→  int value_stride = value.stride(0);
   393→
   394→  dim3 grid(num_tokens);
   395→  dim3 block(std::min(num_heads * head_size, 512));
   396→  const at::cuda::OptionalCUDAGuard device_guard(device_of(key));
   397→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   398→
   399→  DISPATCH_BY_KV_CACHE_DTYPE(key.dtype(), kv_cache_dtype,
   400→                             CALL_RESHAPE_AND_CACHE)
   401→}
