   403→// KV_T is the data type of key and value tensors.
   404→// CACHE_T is the stored data type of kv-cache.
   405→// KV_DTYPE is the real data type of kv-cache.
   406→#define CALL_RESHAPE_AND_CACHE_FLASH(KV_T, CACHE_T, KV_DTYPE)             \
   407→  vllm::reshape_and_cache_flash_kernel<KV_T, CACHE_T, KV_DTYPE>           \
   408→      <<<grid, block, 0, stream>>>(                                       \
   409→          reinterpret_cast<KV_T*>(key.data_ptr()),                        \
   410→          reinterpret_cast<KV_T*>(value.data_ptr()),                      \
   411→          reinterpret_cast<CACHE_T*>(key_cache.data_ptr()),               \
   412→          reinterpret_cast<CACHE_T*>(value_cache.data_ptr()),             \
   413→          slot_mapping.data_ptr<int64_t>(), block_stride, page_stride,    \
   414→          head_stride, key_stride, value_stride, num_heads, head_size,    \
   415→          block_size, reinterpret_cast<const float*>(k_scale.data_ptr()), \
   416→          reinterpret_cast<const float*>(v_scale.data_ptr()));
   417→
   418→void reshape_and_cache_flash(
   419→    torch::Tensor& key,        // [num_tokens, num_heads, head_size]
   420→    torch::Tensor& value,      // [num_tokens, num_heads, head_size]
   421→    torch::Tensor& key_cache,  // [num_blocks, block_size, num_heads, head_size]
   422→    torch::Tensor&
   423→        value_cache,  // [num_blocks, block_size, num_heads, head_size]
   424→    torch::Tensor& slot_mapping,  // [num_tokens] or [num_actual_tokens]
   425→    const std::string& kv_cache_dtype, torch::Tensor& k_scale,
   426→    torch::Tensor& v_scale) {
   427→  // NOTE(woosuk): In vLLM V1, key.size(0) can be different from
   428→  // slot_mapping.size(0) because of padding for CUDA graphs.
   429→  // In vLLM V0, key.size(0) is always equal to slot_mapping.size(0) because
   430→  // both include padding.
   431→  // In vLLM V1, however, key.size(0) can be larger than slot_mapping.size(0)
   432→  // since key includes padding for CUDA graphs, while slot_mapping does not.
   433→  // In this case, slot_mapping.size(0) represents the actual number of tokens
   434→  // before padding.
   435→  // For compatibility with both cases, we use slot_mapping.size(0) as the
   436→  // number of tokens.
   437→  int num_tokens = slot_mapping.size(0);
   438→  int num_heads = key.size(1);
   439→  int head_size = key.size(2);
   440→  int block_size = key_cache.size(1);
   441→
   442→  int64_t key_stride = key.stride(0);
   443→  int64_t value_stride = value.stride(0);
   444→  int64_t block_stride = key_cache.stride(0);
   445→  int64_t page_stride = key_cache.stride(1);
   446→  int64_t head_stride = key_cache.stride(2);
   447→  TORCH_CHECK(key_cache.stride(0) == value_cache.stride(0));
   448→
   449→  dim3 grid(num_tokens);
   450→  dim3 block(std::min(head_size, 512));
   451→  const at::cuda::OptionalCUDAGuard device_guard(device_of(key));
   452→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   453→
   454→  DISPATCH_BY_KV_CACHE_DTYPE(key.dtype(), kv_cache_dtype,
   455→                             CALL_RESHAPE_AND_CACHE_FLASH);
   456→}
   457→
   458→// KV_T is the data type of key and value tensors.
   459→// CACHE_T is the stored data type of kv-cache.
   460→// KV_DTYPE is the real data type of kv-cache.
   461→#define CALL_CONCAT_AND_CACHE_MLA(KV_T, CACHE_T, KV_DTYPE)              \
   462→  vllm::concat_and_cache_mla_kernel<KV_T, CACHE_T, KV_DTYPE>            \
   463→      <<<grid, block, 0, stream>>>(                                     \
   464→          reinterpret_cast<KV_T*>(kv_c.data_ptr()),                     \
   465→          reinterpret_cast<KV_T*>(k_pe.data_ptr()),                     \
   466→          reinterpret_cast<CACHE_T*>(kv_cache.data_ptr()),              \
   467→          slot_mapping.data_ptr<int64_t>(), block_stride, entry_stride, \
   468→          kv_c_stride, k_pe_stride, kv_lora_rank, pe_dim, block_size,   \
   469→          reinterpret_cast<const float*>(scale.data_ptr()));
   470→
   471→void concat_and_cache_mla(
   472→    torch::Tensor& kv_c,          // [num_tokens, kv_lora_rank]
   473→    torch::Tensor& k_pe,          // [num_tokens, pe_dim]
   474→    torch::Tensor& kv_cache,      // [num_blocks, block_size, (kv_lora_rank +
   475→                                  // pe_dim)]
   476→    torch::Tensor& slot_mapping,  // [num_tokens] or [num_actual_tokens]
   477→    const std::string& kv_cache_dtype, torch::Tensor& scale) {
   478→  // NOTE(woosuk): In vLLM V1, key.size(0) can be different from
   479→  // slot_mapping.size(0) because of padding for CUDA graphs.
   480→  // In vLLM V0, key.size(0) is always equal to slot_mapping.size(0) because
   481→  // both include padding.
   482→  // In vLLM V1, however, key.size(0) can be larger than slot_mapping.size(0)
   483→  // since key includes padding for CUDA graphs, while slot_mapping does not.
   484→  // In this case, slot_mapping.size(0) represents the actual number of tokens
   485→  // before padding.
   486→  // For compatibility with both cases, we use slot_mapping.size(0) as the
   487→  // number of tokens.
   488→  int num_tokens = slot_mapping.size(0);
   489→  int kv_lora_rank = kv_c.size(1);
   490→  int pe_dim = k_pe.size(1);
   491→  int block_size = kv_cache.size(1);
   492→
   493→  TORCH_CHECK(kv_cache.size(2) == kv_lora_rank + pe_dim);
   494→
   495→  int kv_c_stride = kv_c.stride(0);
   496→  int k_pe_stride = k_pe.stride(0);
   497→  int block_stride = kv_cache.stride(0);
   498→  int entry_stride = kv_cache.stride(1);
   499→
   500→  dim3 grid(num_tokens);
   501→  dim3 block(std::min(kv_lora_rank, 512));
   502→  const at::cuda::OptionalCUDAGuard device_guard(device_of(kv_c));
   503→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   504→
   505→  DISPATCH_BY_KV_CACHE_DTYPE(kv_c.dtype(), kv_cache_dtype,
   506→                             CALL_CONCAT_AND_CACHE_MLA);
   507→}
