   511→template <typename Tout, typename Tin, Fp8KVCacheDataType kv_dt>
   512→__global__ void convert_fp8_kernel(const Tin* __restrict__ src_cache,
   513→                                   Tout* __restrict__ dst_cache,
   514→                                   const float scale,
   515→                                   const int64_t block_stride) {
   516→  const int64_t block_idx = blockIdx.x;
   517→  for (int i = threadIdx.x; i < block_stride; i += blockDim.x) {
   518→    int64_t idx = block_idx * block_stride + i;
   519→    dst_cache[idx] =
   520→        fp8::scaled_convert<Tout, Tin, kv_dt>(src_cache[idx], scale);
   521→  }
   522→}
