   526→#define CALL_CONVERT_FP8(Tout, Tin, KV_DTYPE)                                \
   527→  vllm::convert_fp8_kernel<Tout, Tin, KV_DTYPE><<<grid, block, 0, stream>>>( \
   528→      reinterpret_cast<Tin*>(src_cache.data_ptr()),                          \
   529→      reinterpret_cast<Tout*>(dst_cache.data_ptr()), scale, block_stride);
