   531→// Only for testing.
   532→void convert_fp8(torch::Tensor& dst_cache, torch::Tensor& src_cache,
   533→                 const double scale, const std::string& kv_cache_dtype) {
   534→  torch::Device src_device = src_cache.device();
   535→  torch::Device dst_device = dst_cache.device();
   536→  TORCH_CHECK(src_device.is_cuda(), "src must be on a GPU")
   537→  TORCH_CHECK(dst_device.is_cuda(), "dst must be on a GPU")
   538→  TORCH_CHECK(src_device.index() == dst_device.index(),
   539→              "src and dst must be on the same GPU");
   540→  at::cuda::OptionalCUDAGuard device_guard(src_device);
   541→
   542→  int64_t num_blocks = src_cache.size(0);
   543→  int64_t block_stride = src_cache.stride(0);
   544→
   545→  dim3 grid(num_blocks);
   546→  dim3 block(std::min(block_stride, int64_t(512)));
   547→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   548→
   549→  if (kv_cache_dtype == "auto") {
   550→    if (src_cache.dtype() == at::ScalarType::Float) {
   551→      CALL_CONVERT_FP8(uint8_t, float, vllm::Fp8KVCacheDataType::kAuto);
   552→    } else if (src_cache.dtype() == at::ScalarType::Half) {
   553→      CALL_CONVERT_FP8(uint8_t, uint16_t, vllm::Fp8KVCacheDataType::kAuto);
   554→    } else if (src_cache.dtype() == at::ScalarType::BFloat16) {
   555→      CALL_CONVERT_FP8(uint8_t, __nv_bfloat16, vllm::Fp8KVCacheDataType::kAuto);
   556→    } else if (dst_cache.dtype() == at::ScalarType::Float) {
   557→      CALL_CONVERT_FP8(float, uint8_t, vllm::Fp8KVCacheDataType::kAuto);
   558→    } else if (dst_cache.dtype() == at::ScalarType::Half) {
   559→      CALL_CONVERT_FP8(uint16_t, uint8_t, vllm::Fp8KVCacheDataType::kAuto);
   560→    } else if (dst_cache.dtype() == at::ScalarType::BFloat16) {
   561→      CALL_CONVERT_FP8(__nv_bfloat16, uint8_t, vllm::Fp8KVCacheDataType::kAuto);
   562→    }
   563→  } else if (kv_cache_dtype == "fp8" || kv_cache_dtype == "fp8_e4m3") {
   564→    if (src_cache.dtype() == at::ScalarType::Float) {
   565→      CALL_CONVERT_FP8(uint8_t, float, vllm::Fp8KVCacheDataType::kFp8E4M3);
   566→    } else if (src_cache.dtype() == at::ScalarType::Half) {
   567→      CALL_CONVERT_FP8(uint8_t, uint16_t, vllm::Fp8KVCacheDataType::kFp8E4M3);
   568→    } else if (src_cache.dtype() == at::ScalarType::BFloat16) {
   569→      CALL_CONVERT_FP8(uint8_t, __nv_bfloat16,
   570→                       vllm::Fp8KVCacheDataType::kFp8E4M3);
   571→    } else if (dst_cache.dtype() == at::ScalarType::Float) {
   572→      CALL_CONVERT_FP8(float, uint8_t, vllm::Fp8KVCacheDataType::kFp8E4M3);
   573→    } else if (dst_cache.dtype() == at::ScalarType::Half) {
   574→      CALL_CONVERT_FP8(uint16_t, uint8_t, vllm::Fp8KVCacheDataType::kFp8E4M3);
   575→    } else if (dst_cache.dtype() == at::ScalarType::BFloat16) {
   576→      CALL_CONVERT_FP8(__nv_bfloat16, uint8_t,
   577→                       vllm::Fp8KVCacheDataType::kFp8E4M3);
