   586→// grid is launched with dimensions (batch, num_splits)
   587→template <typename scalar_t>
   588→__global__ void gather_cache(
   589→    const scalar_t* __restrict__ src_cache,   // [NUM_BLOCKS, BLOCK_SIZE,
   590→                                              // ENTRIES...]
   591→    scalar_t* __restrict__ dst,               // [TOT_TOKENS, ENTRIES...]
   592→    const int32_t* __restrict__ block_table,  // [BATCH, BLOCK_INDICES]
   593→    const int32_t* __restrict__ cu_seq_lens,  // [BATCH+1]
   594→    const int32_t block_size, const int32_t entry_size,
   595→    const int64_t block_table_stride, const int64_t cache_block_stride,
   596→    const int64_t cache_entry_stride, const int64_t dst_entry_stride,
   597→    const int32_t* __restrict__ seq_starts) {  // Optional: starting offsets per
   598→                                               // batch
   599→
   600→  const int64_t bid = blockIdx.x;  // Batch ID
   601→  const int32_t num_splits = gridDim.y;
   602→  const int32_t split = blockIdx.y;
   603→  const int32_t seq_start = cu_seq_lens[bid];
   604→  const int32_t seq_end = cu_seq_lens[bid + 1];
   605→  const int32_t seq_len = seq_end - seq_start;
   606→  const int32_t tot_blocks = cuda_utils::ceil_div(seq_len, block_size);
   607→  const int32_t split_blocks = cuda_utils::ceil_div(tot_blocks, num_splits);
   608→
   609→  const int32_t split_start = split * split_blocks;
   610→  const int32_t split_end = min((split + 1) * split_blocks, tot_blocks);
   611→
   612→  const bool is_active_split = (split_start < tot_blocks);
   613→  const bool is_last_split = (split_end == tot_blocks);
   614→
   615→  if (!is_active_split) return;
   616→
   617→  int32_t full_blocks_end = split_end;
   618→  int32_t partial_block_size = 0;
   619→
   620→  // Adjust the pointer for the block_table for this batch.
   621→  // If seq_starts is provided, compute an offset based on (seq_starts[bid] /
   622→  // page_size)
   623→  const int32_t batch_offset = bid * block_table_stride;
   624→  int32_t offset = 0;
   625→  if (seq_starts != nullptr) {
   626→    offset = seq_starts[bid] / block_size;
   627→  }
   628→  const int32_t* batch_block_table = block_table + batch_offset + offset;
   629→
   630→  // Adjust dst pointer based on the cumulative sequence lengths.
   631→  dst += seq_start * dst_entry_stride;
   632→
   633→  if (is_last_split) {
   634→    partial_block_size = seq_len % block_size;
   635→    if (partial_block_size) full_blocks_end -= 1;
   636→  }
   637→
   638→  auto copy_entry = [&](const scalar_t* __restrict__ _src,
   639→                        scalar_t* __restrict__ _dst) {
   640→    for (int i = threadIdx.x; i < entry_size; i += blockDim.x)
   641→      _dst[i] = _src[i];
   642→  };
   643→
   644→  for (int pid = split_start; pid < full_blocks_end; ++pid) {
   645→    auto block_id = batch_block_table[pid];
   646→    auto block_start_ptr = src_cache + block_id * cache_block_stride;
   647→    auto block_dst_ptr = dst + pid * block_size * dst_entry_stride;
   648→    for (int eid = 0; eid < block_size; ++eid) {
   649→      copy_entry(block_start_ptr + eid * cache_entry_stride,
   650→                 block_dst_ptr + eid * dst_entry_stride);
   651→    }
   652→  }
   653→
   654→  if (partial_block_size) {
   655→    auto block_id = batch_block_table[full_blocks_end];
   656→    auto block_start_ptr = src_cache + block_id * cache_block_stride;
   657→    auto block_dst_ptr = dst + full_blocks_end * block_size * dst_entry_stride;
   658→    for (int eid = 0; eid < partial_block_size; ++eid) {
   659→      copy_entry(block_start_ptr + eid * cache_entry_stride,
   660→                 block_dst_ptr + eid * dst_entry_stride);
   661→    }
   662→  }
   663→}
   664→
   665→}  // namespace vllm
   666→
   667→// Macro to dispatch the kernel based on the data type.
   668→#define CALL_GATHER_CACHE(CPY_DTYPE)                                    \
   669→  vllm::gather_cache<CPY_DTYPE><<<grid, block, 0, stream>>>(            \
   670→      reinterpret_cast<CPY_DTYPE*>(src_cache.data_ptr()),               \
   671→      reinterpret_cast<CPY_DTYPE*>(dst.data_ptr()),                     \
   672→      block_table.data_ptr<int32_t>(), cu_seq_lens.data_ptr<int32_t>(), \
   673→      block_size, entry_size, block_table_stride, cache_block_stride,   \
   674→      cache_entry_stride, dst_entry_stride, seq_starts_ptr);
   675→
   676→// Gather sequences from the cache into the destination tensor.
   677→//  - cu_seq_lens contains the cumulative sequence lengths for each batch
   678→//  - block_table contains the cache block indices for each sequence
   679→//  - Optionally, seq_starts (if provided) offsets the starting block index by
   680→//  (seq_starts[bid] / page_size)
   681→void gather_cache(
   682→    torch::Tensor const& src_cache,    // [NUM_BLOCKS, BLOCK_SIZE, ENTRIES...]
   683→    torch::Tensor const& dst,          // [TOT_TOKENS, ENTRIES...]
   684→    torch::Tensor const& block_table,  // [BATCH, BLOCK_INDICES]
   685→    torch::Tensor const& cu_seq_lens,  // [BATCH+1]
   686→    int64_t batch_size,
   687→    std::optional<torch::Tensor> seq_starts = std::nullopt) {
   688→  at::cuda::OptionalCUDAGuard device_guard(src_cache.device());
   689→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   690→
   691→  int32_t block_size = src_cache.size(1);
   692→  int32_t entry_size = src_cache.flatten(2, -1).size(2);
   693→
   694→  TORCH_CHECK(block_table.dtype() == torch::kInt32,
   695→              "block_table must be int32");
   696→  TORCH_CHECK(cu_seq_lens.dtype() == torch::kInt32,
   697→              "cu_seq_lens must be int32");
   698→  if (seq_starts.has_value()) {
   699→    TORCH_CHECK(seq_starts.value().dtype() == torch::kInt32,
   700→                "seq_starts must be int32");
   701→  }
   702→
   703→  TORCH_CHECK(src_cache.device() == dst.device(),
   704→              "src_cache and dst must be on the same device");
   705→  TORCH_CHECK(src_cache.device() == block_table.device(),
   706→              "src_cache and block_table must be on the same device");
   707→  TORCH_CHECK(src_cache.device() == cu_seq_lens.device(),
   708→              "src_cache and cu_seq_lens must be on the same device");
   709→  if (seq_starts.has_value()) {
   710→    TORCH_CHECK(src_cache.device() == seq_starts.value().device(),
   711→                "src_cache and seq_starts must be on the same device");
   712→  }
   713→
   714→  int64_t block_table_stride = block_table.stride(0);
   715→  int64_t cache_block_stride = src_cache.stride(0);
   716→  int64_t cache_entry_stride = src_cache.stride(1);
   717→  int64_t dst_entry_stride = dst.stride(0);
   718→
   719→  // Decide on the number of splits based on the batch size.
   720→  int num_splits = batch_size > 128 ? 2 : batch_size > 64 ? 4 : 16;
   721→  dim3 grid(batch_size, num_splits);
   722→  dim3 block(1024);
   723→
   724→  TORCH_CHECK(src_cache.dtype() == dst.dtype(),
   725→              "src_cache and dst must have the same dtype");
   726→
   727→  const int dtype_bits = src_cache.element_size() * 8;
   728→  const int32_t* seq_starts_ptr =
   729→      seq_starts.has_value() ? seq_starts.value().data_ptr<int32_t>() : nullptr;
   730→
   731→  if (dtype_bits == 32) {
   732→    CALL_GATHER_CACHE(uint32_t);
   733→  } else if (dtype_bits == 16) {
   734→    CALL_GATHER_CACHE(uint16_t);
   735→  } else if (dtype_bits == 8) {
   736→    CALL_GATHER_CACHE(uint8_t);
   737→  } else {
   738→    TORCH_CHECK(false, "Unsupported data type width: ", dtype_bits);
   739→  }
   740→}
